    cout &lt;&lt; "Xin chao" &lt;&lt; endl;
}
// Trong main:
chaoKhach();</code></pre></div><div class="screen-card"><div class="screen-head">KẾT QUẢ</div><pre>Xin chao</pre></div></div><div class="note-card blue"><h3>Đến lượt em</h3><p>Thêm lời gọi hàm đã cho.</p></div>","challenges":[{"id":"s1-predict","type":"choice","icon":"🔎","title":"Đọc ví dụ: Khi nào lời chào xuất hiện?","prompt":"Đã định nghĩa chaoKhach nhưng main chưa gọi. Hàm có tự in lời chào không?","options":[{"text":"Có","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"Không"}],"answer":"Không","why":"Hàm chỉ chạy khi được gọi."},{"id":"s1-code","type":"code","icon":"⌨️","title":"Đến lượt em: Chào khách","prompt":"Hàm đã có. Thêm lời gọi trong main.","starter":"#include <iostream>
using namespace std;

void chaoKhach() { cout << "Xin chao" << endl; }
int main() {
    // Goi ham o day
    return 0;
}
