inSoLy(3);</code></pre></div><div class="screen-card"><div class="screen-head">KẾT QUẢ</div><pre>So ly: 3</pre></div></div><div class="note-card blue"><h3>Đến lượt em</h3><p>Truyền số vừa nhập vào hàm.</p></div>","challenges":[{"id":"s2-predict","type":"choice","icon":"🔎","title":"Đọc ví dụ: Hàm nhận số nào?","prompt":"inSoLy(4) in gì với hàm trong ví dụ?","options":[{"text":"So ly: 3","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"So ly: 4"}],"answer":"So ly: 4","why":"Tham số soLy nhận giá trị 4 từ lời gọi."},{"id":"s2-code","type":"code","icon":"⌨️","title":"Đến lượt em: In số ly của đơn","prompt":"Chương trình đã nhập n. Sửa lời gọi để truyền n vào hàm.","starter":"#include <iostream>
